+    let weldon = |d: f64| ComponentKind::AdaptiveItem { mcs: ConnectionCode::parse("BT40").expect("BT40"), csw: ConnectionCode::Weldon { d } };
+    assert_eq!(kind, Some(weldon(16.0)), "the workpiece side is the Weldon bore");
